40|export const BLOCKS_PER_STEP = 2;
41|export const FOLD_DISTANCE = 10;
42|export const COMPACT_LEVEL = 4;
43|/** Rows the newest block shows, before any decay. */
44|export const BODY_MAX = 8;
45|/** Rows an opened block shows at most. */
46|export const MAX_FULL_LINES = 400;
47|
48|export function detailFor(distance: number): DetailLevel {
49|  if (distance >= FOLD_DISTANCE) return COMPACT_LEVEL;
50|  return Math.min(COMPACT_LEVEL, Math.floor(distance / BLOCKS_PER_STEP)) as DetailLevel;
51|}
52|
53|export function settleLevel(level: DetailLevel, goal: DetailLevel): DetailLevel {
54|  return level < goal ? level + 1 : goal;
55|}
56|
57|export function maxRowsFor(level: DetailLevel): number {
58|  return level === 0 ? BODY_MAX : Math.max(3, BODY_MAX - level);
59|}
60|
61|export function bodyLinesFor(level: DetailLevel, expanded: boolean): number {
62|  return expanded ? MAX_FULL_LINES : maxRowsFor(level);
63|}
